    const path = this._checkpointPath(tag);
    try {
      await fs.writeFile(path, JSON.stringify(conversation, null, 2), 'utf-8');
    } catch (error) {
      this.debugLogger.error('Error writing to checkpoint file:', error);
    }
  }

