    vi.stubEnv('GEMINI_API_KEY', 'test-api-key');
  });

  afterEach(() => {
    process.argv = originalArgv;
    vi.unstubAllEnvs();
    vi.restoreAllMocks();
  });

  it('should reset context file names to QWEN.md and AGENTS.md by default', async () => {
    process.argv = ['node', 'script.js'];
