            `,
        },
        './bar.txt': 'bar content',
      });

      const defaultProcessMock = vi
        .fn()
        .mockImplementation((p: PromptPipelineContent) =>
          Promise.resolve([
            { text: `${(p[0] as { text: string }).text}-default-processed` },
          ]),
